// Real images generated with Pillow: each carries EXIF/text/comment blocks with a unique
// marker string (and the JPEG/PNG/WebP also a GPS IFD and Orientation=6).
// Used to prove the metadata stripper removes them without damaging the image.
const b = (s) => (s ? Buffer.from(s, 'base64') : null);
module.exports = {
  MARKERS: {"jpeg": "SECRET-LOCATION-MARKER", "jpegComment": "JPEG-COMMENT-MARKER", "png": "PNG-TEXT-MARKER", "webp": "WEBP-EXIF-MARKER", "gif": "GIF-COMMENT-MARKER"},
  jpegWithExif: b(""),
  pngWithMetadata: b(""),
  webpWithExif: b(""),
  gifWithComment: b(""),
};
